insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:environmental-scientist','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Environmental Scientist spans natural-science research under 004-01 and environmental investigation/measurement under 011-99 rather than one exact MHLW small-classification code.','entry_level_basis','Environmental science, earth science and related natural-science study are common foundations; four approved Japanese programmes are retained as direct academic pathways.','qualification_note','No universal statutory licence covers the full Environmental Scientist occupation. Narrower regulated measurement work can require credentials such as 作業環境測定士 or 環境計量士.','market_scope','Research and environmental-investigation market data are not merged into one fabricated exact series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:agronomist','2026-08-10',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 005-01 explicitly includes 農業技術者 and agricultural extension/advisory work covering crops, soils, fertilisers, pests and farm management.','entry_level_basis','Agricultural science, agronomy and related bioscience programmes are common academic foundations; six reviewed Japanese mappings are retained as related pathways rather than occupational qualification.','qualification_note','No universal personal Agronomist licence applies across the canonical role. Public extension or specialist duties can have separate recruitment or appointment requirements.','market_scope','The 005-01 group also contains forestry, livestock and fisheries technicians, so group-level market statistics are not treated as exact Agronomist observations.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:farm-manager','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Japan classifies agricultural production work by production type under 064 rather than publishing one generic Farm Manager small-classification code.','entry_level_basis','Farm management can be reached through agricultural study plus substantial practical production and business experience; six reviewed programmes are retained as related study pathways.','qualification_note','No universal Farm Manager licence applies. Specific pesticide use, machinery, livestock, biosecurity or regulated production duties can carry separate requirements.','market_scope','Crop and livestock production classifications are preserved separately instead of aggregating them into a fabricated generic farm-manager labour series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:forestry-technician','2026-08-10',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 005-01 explicitly includes 林業技術者 covering forest regeneration, protection, utilisation and extension guidance.','entry_level_basis','Forestry, forest science and related agricultural study are common foundations; the reviewed Japanese forest-science programme is retained as related rather than automatic occupational qualification.','qualification_note','No universal personal Forestry Technician licence applies. Relevant credentials such as forestry extension, 技術士, surveying or forestry-skills qualifications can matter for particular roles.','market_scope','005-01 combines agriculture, forestry, livestock and fisheries technical work, so shared statistics are not treated as exact Forestry Technician market values.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:food-technologist','2026-08-10',0,0,0,0,12,0,0,0,5,17,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Food Technologist spans MHLW 006-01 食品開発技術者 and 007-01 食品製造技術者, separating product development from manufacturing/process/quality engineering.','entry_level_basis','Food science, applied bioscience and related agricultural programmes can lead into the field; two reviewed Japanese programmes are retained as related pathways.','qualification_note','There is no universal personal Food Technologist licence. Particular factories, food-safety functions and statutory hygiene roles can have separate qualification requirements.','market_scope','Development and manufacturing technology are kept separate; their labour data are not merged into a fabricated exact Food Technologist series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:sustainability-specialist','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW does not publish one standalone Sustainability Specialist code. Corporate sustainability work can overlap planning/analysis, environmental technical work and consulting depending on duties.','entry_level_basis','Environmental science, engineering, economics, policy and sustainability programmes are relevant; eleven reviewed Japanese programmes are retained as related pathways.','qualification_note','No universal statutory Sustainability Specialist licence applies. Narrow environmental measurement, engineering or consulting responsibilities may carry separate credentials.','market_scope','CampCareer does not substitute environmental-investigation or corporate-planning group data for an exact sustainability-specialist market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:horticulturist','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The broad Horticulturist career spans crop cultivation under 064-02 and plant/nursery/landscape work including 064-05 rather than one exact Japanese code.','entry_level_basis','Horticulture can be entered through vocational, agricultural-science or practical production routes; six reviewed Japanese agriculture programmes are retained as related pathways.','qualification_note','No universal Horticulturist licence applies. Pesticide, machinery, landscaping-construction or supervisory duties can impose role-specific qualifications or training.','market_scope','Crop-production and landscape occupations are not merged into one fabricated horticulture labour series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:animal-science-technician','2026-08-10',0,0,0,0,12,0,0,0,4,16,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 005-01 explicitly includes 畜産技術者 covering breeding, feeding, pasture, production methods and technical guidance.','entry_level_basis','Animal science, agriculture and bioscience study are common foundations; three reviewed Japanese programmes are retained as related pathways.','qualification_note','No universal Animal Science Technician licence covers the broad role. Specific duties such as 家畜人工授精 require separate statutory qualification, and veterinary acts remain outside this profile.','market_scope','005-01 combines livestock with other agriculture/forestry/fisheries technicians, so its statistics are not treated as exact animal-science-technician values.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
